class Solution:
    def numberOfSets(self, n: int, k: int) -> int:
        MOD = 10 ** 9 + 7
        dp = [[0, 0] for _ in range(k + 1)]
        dp[0][0] = 1
        for _ in range(n):
            for j in range(k, 0, -1):
                dp[j][0] = (dp[j][0] + dp[j - 1][1]) % MOD
                dp[j][1] = (dp[j][1] + dp[j][0]) % MOD
            dp[0][1] = (dp[0][1] + dp[0][0]) % MOD
        return dp[k][0]

