    int numberOfSets(int n, int k) {
        const long long MOD = 1e9 + 7;
        int m = n + k - 1;
        vector<long long> fact(m + 1, 1), invFact(m + 1, 1);
        for (int i = 1; i <= m; ++i) fact[i] = fact[i - 1] * i % MOD;
        invFact[m] = modpow(fact[m], MOD - 2, MOD);
        for (int i = m; i >= 1; --i) invFact[i - 1] = invFact[i] * i % MOD;
        return (int)(fact[m] * invFact[2 * k] % MOD * invFact[m - 2 * k] % MOD);
    }
private:
    long long modpow(long long b, long long e, long long mod) {
        long long r = 1;
        while (e > 0) {
            if (e & 1) r = r * b % mod;
            b = b * b % mod;
            e >>= 1;
        }
        return r;
    }
};

